import{DotLottie as o}from"https://esm.sh/@lottiefiles/dotlottie-web";document.querySelectorAll(".descr-tech__item-img canvas").forEach(e=>{const r=e.closest(".descr-tech__item-img").getAttribute("lottie-url");if(console.log(r),r&&r!=="blank"){let t=new o({canvas:e,src:r});window.innerWidth>768?(e.addEventListener("mouseenter",()=>{t.setMode("forward"),t.play()}),e.addEventListener("mouseleave",()=>{t.setMode("reverse"),t.play()})):e.addEventListener("click",()=>{e.hasAttribute("js-expend")?(e.removeAttribute("js-expend"),t.setMode("reverse")):(e.setAttribute("js-expend",""),t.setMode("forward")),t.play()})}});
